require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/Upload.php';require_once __DIR__.'/../core/JalaliDate.php';require_once __DIR__.'/../lib/ManagementMeetingsRepository.php';Auth::requireLogin();if(!ManagementMeetingsRepository::menuAllowed()){http_response_code(403);exit('دسترسی غیرمجاز');}$u=Auth::user();
function mg_meeting_attachments(array $current=[]):array{if(empty($_FILES['attachments']['name'])||!is_array($_FILES['attachments']['name']))return $current;$count=count($_FILES['attachments']['name']);for($i=0;$i<$count;$i++){if(($_FILES['attachments']['error'][$i]??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;$file=['name'=>$_FILES['attachments']['name'][$i],'type'=>$_FILES['attachments']['type'][$i]??'','tmp_name'=>$_FILES['attachments']['tmp_name'][$i],'error'=>$_FILES['attachments']['error'][$i],'size'=>$_FILES['attachments']['size'][$i]];$saved=Upload::save($file,'uploads/management-meetings',['pdf','doc','docx','xls','xlsx','jpg','jpeg','png','webp'],10*1024*1024);if(!$saved['ok'])throw new InvalidArgumentException($saved['error']);$current[]=['original_name'=>$saved['original_name'],'file_path'=>$saved['file_path'],'mime_type'=>$saved['mime_type'],'file_size'=>$saved['file_size']];}return array_slice($current,0,20);}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');$action=(string)($_POST['action']??'create');$id=(int)($_POST['id']??0);if($action==='create'){$_POST['attachments']=mg_meeting_attachments();$id=ManagementMeetingsRepository::createMeeting($_POST,(int)$u['id']);flash('صورتجلسه با موفقیت ثبت شد.');redirect('/admin/management-meeting-view.php?id='.$id);}if($action==='update'){$old=ManagementMeetingsRepository::getMeetingById($id);$_POST['attachments']=mg_meeting_attachments($old['attachments']??[]);ManagementMeetingsRepository::updateMeeting($id,$_POST,(int)$u['id']);flash('صورتجلسه بروزرسانی شد.');}elseif($action==='finalize'){ManagementMeetingsRepository::finalizeMeeting($id,(int)$u['id']);flash('صورتجلسه نهایی شد.');}elseif($action==='archive'){ManagementMeetingsRepository::archiveMeeting($id,(int)$u['id']);flash('صورتجلسه بایگانی شد.');}redirect('/admin/management-meetings.php');}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Management meetings page: '.$e->getMessage());flash('انجام عملیات صورتجلسه ممکن نشد.','danger');}redirect('/admin/management-meetings.php');}
$filterMeetingDate=JalaliDate::toGregorian((string)($_GET['meeting_date']??''))?:trim((string)($_GET['meeting_date']??''));$filters=['meeting_type'=>trim((string)($_GET['meeting_type']??'')),'meeting_date'=>$filterMeetingDate,'status'=>trim((string)($_GET['status']??'')),'organizer_user_id'=>(int)($_GET['organizer_user_id']??0),'secretary_user_id'=>(int)($_GET['secretary_user_id']??0)];$rows=ManagementMeetingsRepository::getMeetings($filters,$u);$stats=ManagementMeetingsRepository::meetingStats($u);$users=ManagementMeetingsRepository::users();$edit=!empty($_GET['edit'])?ManagementMeetingsRepository::getMeetingById((int)$_GET['edit'],$u):null;$pageTitle='قوانین مصوب و صورتجلسات';$adminExtraStylesheets=['/assets/css/management-governance.css'];$adminExtraScripts=['/assets/js/management-meetings-jalali.js'];require __DIR__.'/../views/partials/admin-header.php';?>
<div class="mg-page"><header class="mg-hero"><div><small>مدیریت جلسات و تعهدات سازمانی</small><h1>قوانین مصوب و صورتجلسات</h1><p>ثبت جلسه، پیگیری مصوبات و نگهداری نسخه‌های قوانین</p></div><?php if(ManagementMeetingsRepository::canCreateMeeting($u)):?><a class="btn" href="#meetingForm">ثبت صورتجلسه جدید</a><?php endif?></header><?php require __DIR__.'/includes/management-governance-nav.php';?><section class="mg-kpis"><?php foreach(['meetings'=>'کل صورتجلسات','month_meetings'=>'جلسات ماه','open'=>'مصوبات باز','overdue'=>'عقب‌افتاده','done'=>'انجام‌شده','rules'=>'قوانین فعال'] as $k=>$label):?><article class="mg-kpi"><span><?=e($label)?></span><strong><?=format_number($stats[$k])?></strong></article><?php endforeach?></section>
<section class="card"><form class="mg-filter" method="get"><label>نوع جلسه<input name="meeting_type" value="<?=e($filters['meeting_type'])?>"></label><label>تاریخ جلسه<input class="jalali-date-input" name="meeting_date" value="<?=e(JalaliDate::toJalali($filters['meeting_date']))?>"></label><label>وضعیت<select name="status"><option value="">همه</option><?php foreach(ManagementMeetingsRepository::MEETING_STATUSES as $k=>$v):?><option value="<?=$k?>" <?=$filters['status']===$k?'selected':''?>><?=e($v)?></option><?php endforeach?></select></label><label>برگزارکننده<select name="organizer_user_id"><option value="">همه</option><?php foreach($users as $x):?><option value="<?=$x['id']?>" <?=$filters['organizer_user_id']==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach?></select></label><div class="mg-actions"><button class="btn btn-primary">اعمال فیلتر</button><a class="btn" href="/admin/management-meetings.php">پاکسازی</a></div></form></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>نوع / تاریخ</th><th>برگزارکننده</th><th>دبیر</th><th>مصوبات</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['title'])?></strong><small><?=e(format_jalali_datetime($r['created_at']))?></small></td><td><?=e($r['meeting_type'])?><small><?=e(JalaliDate::toJalali($r['meeting_date']))?></small></td><td><?=e($r['organizer_name']??'—')?></td><td><?=e($r['secretary_name']??'—')?></td><td><?=format_number($r['decision_count'])?></td><td><span class="mg-badge"><?=e(ManagementMeetingsRepository::MEETING_STATUSES[$r['status']]??$r['status'])?></span></td><td><div class="mg-actions"><a class="btn btn-small" href="/admin/management-meeting-view.php?id=<?=$r['id']?>">جزئیات</a><?php if(ManagementMeetingsRepository::canCreateMeeting($u)&&$r['status']!=='archived'):?><a class="btn btn-small" href="?edit=<?=$r['id']?>#meetingForm">ویرایش</a><form method="post"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-small" name="action" value="finalize">نهایی‌سازی</button><button class="btn btn-small" name="action" value="archive">بایگانی</button></form><?php endif?></div></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="7"><div class="mg-empty">صورتجلسه‌ای مطابق فیلترها پیدا نشد.</div></td></tr><?php endif?></tbody></table></div></section>
<?php if(ManagementMeetingsRepository::canCreateMeeting($u)):?><section class="card" id="meetingForm"><h2><?=$edit?'ویرایش صورتجلسه':'ثبت صورتجلسه جدید'?></h2><form method="post" enctype="multipart/form-data" class="mg-form-grid"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>عنوان جلسه<input name="title" maxlength="255" required value="<?=e($edit['title']??'')?>"></label><label>نوع جلسه<input name="meeting_type" maxlength="50" required value="<?=e($edit['meeting_type']??'general')?>"></label><label>تاریخ جلسه<input class="jalali-date-input" name="meeting_date" inputmode="numeric" placeholder="1405/01/01" required value="<?=e(JalaliDate::toJalali($edit['meeting_date']??date('Y-m-d')))?>"></label><label>محل برگزاری<input name="location" maxlength="255" value="<?=e($edit['location']??'')?>"></label><label>ساعت شروع<input type="time" name="start_time" value="<?=e(substr((string)($edit['start_time']??''),0,5))?>"></label><label>ساعت پایان<input type="time" name="end_time" value="<?=e(substr((string)($edit['end_time']??''),0,5))?>"></label><label>برگزارکننده<select name="organizer_user_id"><option value="">انتخاب</option><?php foreach($users as $x):?><option value="<?=$x['id']?>" <?=(int)($edit['organizer_user_id']??0)==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach?></select></label><label>دبیر جلسه<select name="secretary_user_id"><option value="">انتخاب</option><?php foreach($users as $x):?><option value="<?=$x['id']?>" <?=(int)($edit['secretary_user_id']??0)==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach?></select></label><label>حاضرین<select name="attendees[]" multiple size="7"><?php foreach($users as $x):?><option value="<?=$x['id']?>" <?=in_array((int)$x['id'],$edit['attendees']??[],true)?'selected':''?>><?=e($x['name'])?></option><?php endforeach?></select></label><label>غایبین<select name="absent_users[]" multiple size="7"><?php foreach($users as $x):?><option value="<?=$x['id']?>" <?=in_array((int)$x['id'],$edit['absent_users']??[],true)?'selected':''?>><?=e($x['name'])?></option><?php endforeach?></select></label><label class="wide">دستور جلسه<textarea name="agenda" rows="4"><?=e($edit['agenda']??'')?></textarea></label><label class="wide">خلاصه مذاکرات<textarea name="meeting_summary" rows="6"><?=e($edit['meeting_summary']??'')?></textarea></label><label class="wide">پیوست‌ها<input type="file" name="attachments[]" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.webp"></label><div class="wide"><button class="btn btn-primary">ذخیره تغییرات</button></div></form></section><?php endif?></div><?php require __DIR__.'/../views/partials/admin-footer.php';?>
